#include <vector>

class Solution {
public:
    int countMaxOrSubsets(std::vector<int>& nums) {
        int maxOr = 0;
        for (int x : nums) maxOr |= x;

        int count = 0;
        int n = nums.size();

        auto dfs = [&](auto& self, int idx, int currOr) -> void {
            if (idx == n) {
                if (currOr == maxOr) count++;
                return;
            }
            self(self, idx + 1, currOr | nums[idx]);
            self(self, idx + 1, currOr);
        };

        dfs(dfs, 0, 0);
        return count;
    }
};

class Solution {
    private int count = 0;
    private int maxOr = 0;

    public int countMaxOrSubsets(int[] nums) {
        for (int x : nums) maxOr |= x;
        dfs(nums, 0, 0);
        return count;
    }

    private void dfs(int[] nums, int idx, int currOr) {
        if (idx == nums.length) {
            if (currOr == maxOr) count++;
            return;
        }
        dfs(nums, idx + 1, currOr | nums[idx]);
        dfs(nums, idx + 1, currOr);
    }
}

