var countMaxOrSubsets = function(nums) {
    let maxOr = 0;
    for (const x of nums) maxOr |= x;

    let count = 0;
    const n = nums.length;

    function dfs(idx, currOr) {
        if (idx === n) {
            if (currOr === maxOr) count++;
            return;
        }
        dfs(idx + 1, currOr | nums[idx]);
        dfs(idx + 1, currOr);
    }

    dfs(0, 0);
    return count;
};
